exercises.solution:
const ram = ['A', 'B', 'C'];
const MAX = 3;
function load(page) {
  if (ram.length >= MAX) {
    ram.shift();
    console.log('evicted');
  }
  ram.push(page);
  console.log('loaded ' + page);
}
load('D');

